fix.code:
-- 1. Dọn dữ liệu trùng trước, rồi thêm ràng buộc trên email đã chuẩn hoá
--    (CONCURRENTLY không chạy trong transaction: với Flyway, để migration này non-transactional)
CREATE UNIQUE INDEX CONCURRENTLY ux_users_email ON users (lower(email));

// 2. Chuẩn hoá email một lần ở biên, để query dùng được đúng index
@Transactional
public User register(String rawEmail, String password) {
    String email = rawEmail.strip().toLowerCase(Locale.ROOT);
    if (userRepository.existsByEmail(email)) {          // trả lỗi sớm cho trường hợp thường gặp
        throw new EmailAlreadyUsedException(email);
    }
    try {
        return userRepository.saveAndFlush(new User(email, passwordEncoder.encode(password)));
    } catch (DataIntegrityViolationException e) {
        if (isUniqueViolation(e, "ux_users_email")) {    // chỉ dịch đúng lỗi trùng email
            throw new EmailAlreadyUsedException(email);
        }
        throw e;
    }
}
